"""plugins/assigned_today.py - 📌 Назначено на день."""
__version__ = '1.1'
__description__ = ('📌 Назначено на день: столбцы 1–4/auto, фильтр по гипотезе/заданию '
                   '(item-level assignees + hyp_item_id), режимы список/компакт/таблица/группа, '
                   'сортировка, просрочка, «Отметить всё», прогресс дня, localStorage')

import json
