<div class="list cols-auto" id="atList"><div class="empty">Загрузка…</div></div>
</div>
<div class="toast" id="atToast"></div>
<script>
(function(){
'use strict';
var LS='assigned_today_view_v105';
var view={mode:'cards',cols:'auto',sort:'count',hideLogged:false,q:''};
var colsUser=false;/* был ли выбор столбцов сделан вручную (тогда не перебиваем серверным) */
try{var sv=JSON.parse(localStorage.getItem(LS)||'{}');for(var k in view)if(sv[k]!==undefined)view[k]=sv[k];colsUser=!!sv.colsUser;}catch(e){}
function saveView(){view.colsUser=colsUser;try{localStorage.setItem(LS,JSON.stringify(view));}catch(e){}}
function saveColsServer(c){/* PATCH v1.0.5: серверное сохранение числа столбцов (общее для всех) */
  try{fetch('/api/plugins/assigned_today/columns',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf()},body:JSON.stringify({columns:c})}).catch(function(){});}catch(e){}}
var DATA=null,lastClick=0;
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function fmtDate(iso){if(!iso)return'';var p=iso.split('-');return p[2]+'.'+p[1]+'.'+p[0];}
function statusCls(s){if(s==='done')return'ok';if(s==='paused')return'warn';return'';}
function toast(msg){var t=document.getElementById('atToast');t.textContent=msg;t.classList.add('show');clearTimeout(t._tm);t._tm=setTimeout(function(){t.classList.remove('show');},2200);}
function init(e){return String(e.employee_name||'?').trim().split(/\\s+/).slice(0,2).map(function(w){return w[0]||'';}).join('').toUpperCase();}
function matchQ(t,e){if(!view.q)return true;var q=view.q.toLowerCase();var hay=(e.employee_name+' '+t.name+' '+(t.tags||[]).join(' ')+' '+(t.hypotheses||[]).map(function(h){return h.title+' '+h.jobs.map(function(j){return j.title;}).join(' ');}).join(' ')).toLowerCase();return hay.indexOf(q)>=0;}
function empTasks(e){return (e.tasks||[]).filter(function(t){if(view.hideLogged&&t.logged)return false;return matchQ(t,e);});}
function taskVisible(e){return empTasks(e).length>0;}
/* ---------- рендер: карточка задачи ---------- */
function hypHtml(h){
  var jobs=(h.jobs||[]).map(function(j){
    return '<div class="hyp-task-row"><span class="hyp-ico">'+esc(j.status_label)+'</span><span class="hyp-task-name">'+esc(j.title)+'</span></div>';
  }).join('');
  return '<div class="hyp-block"><div class="hyp-row"><span class="hyp-ico">'+esc(h.status_label)+'</span><span class="hyp-title">'+esc(h.title)+'</span></div>'+(jobs?'<div class="hyp-tasks">'+jobs+'</div>':'')+'</div>';
}
function taskHtml(t){
  var tags=(t.tags||[]).map(function(x){return '<span class="tag">#'+esc(x)+'</span>';}).join('');
  var hyps=(t.hypotheses||[]).map(function(h){h._tid=t.task_id;return hypHtml(h);}).join('');
  var desc=t.description?'<div class="desc">'+esc(t.description)+'</div>':'';
  var dl=t.deadline?'<span class="meta">⏰ '+esc(fmtDate(t.deadline))+'</span>':'';
  var cls='task-row'+(t.is_urgent?' urg':'')+(t.overdue?' od':'')+(t.logged?' lg':'');
  var urg=t.is_urgent?'<span class="badge urg">🚨 срочно</span>':'';
  var od=t.overdue?'<span class="badge od">просрочено</span>':'';
  var lgd=t.logged?'<span class="badge ok">отмечено '+esc(t.logged_hours)+'ч</span>':'';
  var flt=t.filtered?'<span class="badge flt">только мои пункты</span>':'';
  var allBtn=(t.open_items&&t.open_items.length)?'<div class="tfoot"><button class="btn-all" data-task="'+esc(t.task_id)+'" data-open="'+esc(JSON.stringify(t.open_items))+'">✅ Отметить всё ('+t.open_items.length+')</button></div>':'';
  return '<div class="'+cls+'"><div class="task-head"><span class="task-ico">'+esc(t.icon||'📋')+'</span><span class="task-name">'+esc(t.name)+'</span>'+urg+od+flt+lgd+'<span class="badge '+statusCls(t.status)+'">'+esc(t.status_label)+'</span>'+dl+'</div>'+desc+(tags?'<div class="tags">'+tags+'</div>':'')+(hyps?'<div class="hyps">'+hyps+'</div>':'')+allBtn+'</div>';
}
function empCard(e){
  var bg=esc(e.employee_color||'#888');
  var tasks=empTasks(e);
  var pct=Math.min(100,Math.round((e.logged_hours||0)/8*100));
  var vac=e.on_vacation?'<span class="badge warn">🏖 отпуск</span>':'';
  return '<div class="emp-card" data-eid="'+esc(e.employee_id)+'"><div class="emp-head"><div class="emp-av" style="background:'+bg+'">'+esc(init(e))+'</div><div class="emp-body"><div class="emp-name">'+esc(e.employee_name)+' '+vac+'</div>'+(e.department?'<div class="emp-dept">🏢 '+esc(e.department)+'</div>':'')+'<div class="prog" title="'+esc(e.logged_hours)+' из 8 ч"><i style="width:'+pct+'%"></i></div></div><div class="emp-cnt">'+tasks.length+'</div></div><div class="emp-tasks">'+tasks.map(taskHtml).join('')+'</div></div>';
}
/* ---------- компактный ---------- */
function empChips(e){
  var bg=esc(e.employee_color||'#888');
  var tasks=empTasks(e);
  var chips=tasks.map(function(t){
    var items=(t.open_items&&t.open_items.length)?t.open_items.map(function(j){return '<span class="chip mine" title="'+esc(j.hyp_title)+'">📌 '+esc(j.title)+'</span>';}).join(''):(t.filtered?'<span class="chip">— всё закрыто —</span>':'');
    return '<div class="task-row'+(t.overdue?' od':'')+'"><div class="task-head"><span class="task-ico">'+esc(t.icon||'📋')+'</span><span class="task-name">'+esc(t.name)+'</span>'+(t.overdue?'<span class="badge od">⏰</span>':'')+(t.logged?'<span class="badge ok">'+esc(t.logged_hours)+'ч</span>':'')+'</div><div class="chip-line">'+chips+'</div></div>';
  }).join('');
  return '<div class="emp-card" data-eid="'+esc(e.employee_id)+'"><div class="emp-head"><div class="emp-av" style="background:'+bg+'">'+esc(init(e))+'</div><div class="emp-body"><div class="emp-name">'+esc(e.employee_name)+'</div>'+(e.department?'<div class="emp-dept">🏢 '+esc(e.department)+'</div>':'')+'</div><div class="emp-cnt">'+tasks.length+'</div></div><div class="emp-tasks">'+chips+'</div></div>';
}
/* ---------- таблица ---------- */
function tableHtml(emps){
  var rows=[];
  emps.forEach(function(e){empTasks(e).forEach(function(t){
    var myH=(t.hypotheses||[]).map(function(h){
      var jj=h.jobs.filter(function(j){return !t.filtered||(t.open_items||[]).some(function(o){return o.id===j.id;})||j.status==='done';}).map(function(j){return esc(j.status_label)+' '+esc(j.title);});
      return '🧪 '+esc(h.title)+(jj.length?'<br>&nbsp;&nbsp;'+jj.join('<br>&nbsp;&nbsp;'):'');
    }).join('<br>');
    rows.push('<tr class="'+(t.overdue?'od':'')+'"><td><span class="emp-av" style="background:'+esc(e.employee_color||'#888')+';width:20px;height:20px;font-size:.55rem;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;color:#fff;font-weight:800">'+esc(init(e))+'</span> '+esc(e.employee_name)+'</td><td>'+esc(t.icon||'📋')+' '+esc(t.name)+(t.is_urgent?' <span class="badge urg">🚨</span>':'')+(t.overdue?' <span class="badge od">просрочено</span>':'')+'</td><td>'+esc(t.status_label)+'</td><td class="meta">'+esc(fmtDate(t.deadline))+'</td><td class="meta">'+esc(t.logged_hours||0)+' ч</td><td>'+myH+'</td></tr>');
  });});
  if(!rows.length)return '';
  return '<div class="tblwrap"><table class="at"><thead><tr><th>Сотрудник</th><th>Задача</th><th>Статус</th><th>Дедлайн</th><th>Часы</th><th>Гипотезы / задания'+(view.q?' (мои)':'')+'</th></tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';
}
/* ---------- группировка по гипотезам ---------- */
function hypGroupHtml(emps){
  var map={};
  emps.forEach(function(e){empTasks(e).forEach(function(t){(t.hypotheses||[]).forEach(function(h){
    var key=h.title||'(без названия)';
    var m=map[key]||(map[key]={title:h.title,status_label:h.status_label,jobs:{},people:{}});
    (h.jobs||[]).forEach(function(j){m.jobs[j.id]=j;});
    m.people[e.employee_id]=e;
  });});});
  var keys=Object.keys(map).sort(function(a,b){return a.localeCompare(b,'ru');});
  if(!keys.length)return '';
  return keys.map(function(k){var m=map[k];
    var avs=Object.keys(m.people).map(function(pid){var e=m.people[pid];return '<span class="emp-av" style="background:'+esc(e.employee_color||'#888')+'" title="'+esc(e.employee_name)+'">'+esc(init(e))+'</span>';}).join('');
    var jobs=Object.keys(m.jobs).map(function(jid){var j=m.jobs[jid];return '<div class="hg-row"><span>'+esc(j.status_label)+'</span><span class="hyp-task-name">'+esc(j.title)+'</span></div>';}).join('');
    return '<div class="hyp-group"><h3>'+esc(m.status_label)+' '+esc(m.title)+'</h3><div class="avatars" style="display:flex;margin-bottom:6px">'+avs+'</div>'+jobs+'</div>';
  }).join('');
}
/* ---------- сортировка ---------- */
function sortEmps(emps){
  var s=view.sort,arr=emps.slice();
  function minDl(e){var d='9999';empTasks(e).forEach(function(t){if(t.deadline&&t.deadline<d)d=t.deadline;});return d;}
  if(s==='name')arr.sort(function(a,b){return a.employee_name.localeCompare(b.employee_name,'ru');});
  else if(s==='urgent')arr.sort(function(a,b){function u(e){return empTasks(e).some(function(t){return t.is_urgent;})?0:1;}return u(a)-u(b)||b.tasks_count-a.tasks_count;});
  else if(s==='deadline')arr.sort(function(a,b){return minDl(a)<minDl(b)?-1:minDl(a)>minDl(b)?1:0;});
  else arr.sort(function(a,b){return b.tasks_count-a.tasks_count||a.employee_name.localeCompare(b.employee_name,'ru');});
  return arr;
}
function render(){
  if(!DATA)return;
  var el=document.getElementById('atList');
  el.className='list cols-'+view.cols+(view.mode==='chips'?' mode-chips':'');
  var emps=sortEmps(DATA.employees.filter(taskVisible));
  if(!emps.length){el.innerHTML='<div class="empty">Ничего не найдено</div>';return;}
  if(view.mode==='table'){el.innerHTML=tableHtml(emps);el.className='list cols-1';return;}
  if(view.mode==='hypgroup'){el.innerHTML=hypGroupHtml(emps);el.className='list cols-'+view.cols;return;}
  el.innerHTML=emps.map(view.mode==='chips'?empChips:empCard).join('');
}
function renderKpis(){
  var t=DATA.totals;
  document.getElementById('atKpis').innerHTML=
   '<div class="kpi"><div class="v">'+t.employees_with_tasks+'</div><div class="l">Сотрудников с задачами</div></div>'+
   '<div class="kpi"><div class="v">'+t.tasks_assignments+'</div><div class="l">Назначений задач</div></div>'+
   '<div class="kpi"><div class="v">'+t.open_items+'</div><div class="l">Открытых пунктов (моих)</div></div>'+
   '<div class="kpi"><div class="v">'+(DATA.week_due_items||0)+'</div><div class="l">Пункты с дедлайном ≤7 дней</div></div>';
}
/* ---------- PATCH v1.0.5: пакетная отметка пункта гипотезы ---------- */
function csrf(){return window.REESTR_CSRF||'';}
document.getElementById('atList').addEventListener('click',function(ev){
  var a=ev.target.closest('.btn-all');if(!a)return;
  var now=Date.now();if(now-lastClick<600)return;/* кулдаун против двойного клика */
  lastClick=now;
  var tid=a.getAttribute('data-task');
  var items=[];try{items=JSON.parse(a.getAttribute('data-open')||'[]');}catch(e){}
  var card=a.closest('.emp-card');
  var empId=card?card.getAttribute('data-eid'):'';
  if(!items.length||!empId){toast('Нечего отмечать');return;}
  var dk=document.getElementById('atDate').value;
  a.classList.add('busy');a.textContent='⏳ Отмечаю…';
  var doneCnt=0,failCnt=0;
  function next(){
    if(!items.length){
      toast(failCnt?('Готово, ошибок: '+failCnt):('✅ Отмечено пунктов: '+doneCnt));
      load();return;
    }
    var j=items.shift();
    fetch('/api/plugins/assigned_today/mark_item',{method:'POST',credentials:'same-origin',
      headers:{'Content-Type':'application/json','X-CSRF-Token':csrf()},
      body:JSON.stringify({date:dk,employee_id:empId,task_id:tid,hyp_item_id:j.id})})
    .then(function(r){return r.json().then(function(d){return{ok:r.ok&&d&&d.success,err:(d&&(d.error||d.message))||''};});})
    .then(function(res){if(res.ok)doneCnt++;else failCnt++;next();})
    .catch(function(){failCnt++;next();});
  }
  next();
});
/* ---------- панель управления ---------- */
function setSeg(id,key,val){
  document.getElementById(id).querySelectorAll('[data-m],[data-c]').forEach(function(b){
    var v=b.getAttribute('data-m')||b.getAttribute('data-c');
    b.classList.toggle('on',String(v)===String(val));
  });
  void key;
}
document.getElementById('atModes').addEventListener('click',function(ev){
  var b=ev.target.closest('button[data-m]');if(!b)return;
  view.mode=b.getAttribute('data-m');setSeg('atModes','mode',view.mode);saveView();render();
});
document.getElementById('atCols').addEventListener('click',function(ev){
  var b=ev.target.closest('button[data-c]');if(!b)return;
  view.cols=b.getAttribute('data-c');colsUser=true;
  setSeg('atCols','cols',view.cols);saveView();saveColsServer(view.cols==='auto'?0:view.cols);render();
});
document.getElementById('atSort').addEventListener('change',function(){view.sort=this.value;saveView();render();});
document.getElementById('atHideLogged').addEventListener('change',function(){view.hideLogged=this.checked;saveView();render();});
document.getElementById('atSearch').addEventListener('input',function(){view.q=this.value.trim();saveView();render();});
/* ---------- загрузка ---------- */
function load(){
  var dk=document.getElementById('atDate').value;
  document.getElementById('atList').innerHTML='<div class="empty">Загрузка…</div>';
  fetch('/api/plugins/assigned_today/data?date='+encodeURIComponent(dk),{credentials:'same-origin'})
    .then(function(r){return r.json();})
    .then(function(d){
      if(!d||!d.success){document.getElementById('atList').innerHTML='<div class="empty" style="color:#ec7063">Ошибка</div>';return;}
      DATA=d;
      if(!colsUser&&d.columns){view.cols=String(d.columns);setSeg('atCols','cols',view.cols);}
      renderKpis();render();
    })
    .catch(function(){document.getElementById('atList').innerHTML='<div class="empty" style="color:#ec7063">Ошибка соединения</div>';});
}
document.getElementById('atApply').addEventListener('click',load);
document.getElementById('atDate').addEventListener('change',load);
document.getElementById('atExport').addEventListener('click',function(){
  var dk=document.getElementById('atDate').value;
  window.location.href='/api/plugins/assigned_today/export.xlsx?date='+encodeURIComponent(dk);
});
document.getElementById('atDate').value=new Date().toISOString().slice(0,10);
setSeg('atModes','mode',view.mode);setSeg('atCols','cols',view.cols);
